import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int m = sc.nextInt();
        double[] p = new double[n];
        double[] q = new double[n];
        double[] res = new double[1 << n];

        for (int i = 0; i < n; i++) {
            p[i] = sc.nextDouble();
            res[1 << i] = p[i];
            q[i] = 0.0;
        }

        for (int mask = 1; mask < (1 << n); mask++) {
            List<Integer> selected = new ArrayList<>();
            List<Integer> unselected = new ArrayList<>();
            double sum_unselected = 0.0;

            for (int j = 0; j < n; j++) {
                if (((mask >> j) & 1) == 1) {
                    selected.add(j);
                } else {
                    unselected.add(j);
                    sum_unselected += p[j];
                }
            }

            if (selected.size() == m || (selected.size() < m && sum_unselected < 1e-5)) {
                for (int x : selected) {
                    q[x] += res[mask];
                }
            } else if (selected.size() < m) {
                for (int x : unselected) {
                    int nextMask = mask | (1 << x);
                    res[nextMask] += res[mask] * p[x] / sum_unselected;
                }
            }
        }

        for (int i = 0; i < n; i++) {
            System.out.printf("%.15f ", q[i]);
        }
        System.out.println();
        sc.close();
    }
}
